commands.run:
b="$(git merge-base origin/main HEAD)" || exit 1; git diff --name-only --diff-filter=AM "$b" HEAD | python3 -c "import sys
bad = []
new = {'claude/hooks/marker_sha_guard.py', 'claude/hooks/marker-sha-guard.test.sh'}
for p in sys.stdin.read().split():
    data = open(p, 'rb').read()
    if b'\r' in data: bad.append(p + ': CR')
    if p in new and any(c > 127 for c in data): bad.append(p + ': non-ASCII')
print('\n'.join(bad)); sys.exit(1 if bad else 0)
"
